#include <iostream>

int main() {
    int a = 5;  // First operand
    int b = 3;  // Second operand
    int c = 2;  // Third operand

    // Without parentheses: Multiplication has higher precedence
    int result1 = a + b * c;  // Evaluates as a + (b * c)

    // With parentheses: Forces addition first
    int result2 = (a + b) * c;  // Evaluates as ((a + b) * c)

    std::cout << "Result without parentheses: " << result1 << std::endl;  // Outputs 11"
    std::cout << "Result with parentheses: " << result2 << std::endl;  // Outputs 16"
    return 0;
}
